// logRequests writes one log line per request: method, path, the route pattern that
// matched (r.Pattern, set by the ServeMux), status, size, queries, and duration. It
// never logs bodies, which can hold passwords.
func (s *server) logRequests(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		rec := &statusRecorder{ResponseWriter: w}
		next.ServeHTTP(rec, r)
		level := slog.LevelInfo
		if rec.status() >= http.StatusInternalServerError {
			level = slog.LevelError
		}
		s.Log.LogAttrs(r.Context(), level, "request",
			slog.String("request_id", requestIDFrom(r.Context())),
			slog.String("method", r.Method),
			slog.String("path", r.URL.Path),
			slog.String("pattern", r.Pattern),
			slog.Int("status", rec.status()),
			slog.Int64("bytes", rec.bytes),
			slog.Int64("queries", metrics.QueryCount(r.Context())),
			slog.Float64("duration_ms", math.Round(float64(time.Since(start).Microseconds()))/1000),
		)
	})
}

// requireAuth lets a request through only with a valid token, and puts its user in
// the context for the handlers (auth.UserFrom). The token comes from
// "Authorization: Bearer <token>", or, when there is no Authorization header, the
// tb_session cookie. A header that is present decides alone, so a bad bearer token is
// refused even next to a good cookie.
func (s *server) requireAuth(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		token, err := credentials(r)
		if err != nil {
			s.writeProblem(w, r, err)
			return
		}
		user, err := s.Auth.Authenticate(r.Context(), token)
		if err != nil {
			s.writeProblem(w, r, err)
			return
		}
		next.ServeHTTP(w, r.WithContext(auth.WithUser(r.Context(), user)))
	})
}

// readyz answers whether the server can do its job right now: the database must
// answer a ping within a second. A load balancer sends traffic only while it says 200.
func (s *server) readyz(w http.ResponseWriter, r *http.Request) error {
	ctx, cancel := context.WithTimeout(r.Context(), time.Second)
	defer cancel()
	if err := s.Ready(ctx); err != nil {
		state := "error"
		if errors.Is(err, context.DeadlineExceeded) {
			state = "timeout"
		}
		s.Log.WarnContext(ctx, "not ready", "db", state, "err", err)
		return writeJSON(w, http.StatusServiceUnavailable, readyResponse{Status: "not_ready", Checks: map[string]string{"db": state}})
	}
	return writeJSON(w, http.StatusOK, readyResponse{Status: "ready", Checks: map[string]string{"db": "ok"}})
}

// do sends one request through the handler in memory and returns the recorded
// response. headers are name, value pairs.
func (a testAPI) do(t *testing.T, method, path, token, body string, headers ...string) *httptest.ResponseRecorder {
	t.Helper()
	req := httptest.NewRequestWithContext(t.Context(), method, path, strings.NewReader(body))
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	if body != "" {
		req.Header.Set("Content-Type", "application/json")
	}
	for i := 0; i+1 < len(headers); i += 2 {
		req.Header.Set(headers[i], headers[i+1])
	}
	rec := httptest.NewRecorder()
	a.handler.ServeHTTP(rec, req)
	return rec
}

func TestCreateTaskRejects(t *testing.T) {
	tests := []struct {
		name   string
		body   string
		status int
		field  string
	}{
		{"an empty title", `{"title": "   "}`, 422, "title"},
		{"priority 4", `{"title": "Ship it", "priority": 4}`, 422, "priority"},
		{"priority as a word", `{"title": "Ship it", "priority": "high"}`, 400, "priority"},
		{"a date that does not exist", `{"title": "Ship it", "due_on": "2026-13-01"}`, 422, "due_on"},
		{"an assignee outside the project", `{"title": "Ship it", "assignee_id": 4}`, 422, "assignee_id"},
		{"status, which is not a field here", `{"title": "Ship it", "status": "done"}`, 400, "status"},
		{"a body that is not JSON", `{"title": `, 400, ""},
		{"two JSON objects", `{"title": "a"}{"title": "b"}`, 400, ""},
	}
	a := newTestAPI(t)
	token := a.as(graceID)
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			rec := a.do(t, "POST", "/v1/projects/1/tasks", token, tc.body)
			wantStatus(t, rec, tc.status)
			if p := decode[problem](t, rec); tc.field != "" && p.Errors[tc.field] == "" {
				t.Errorf("errors = %v, want one for %s", p.Errors, tc.field)
			}
		})
	}
}

func TestDeleteCascades(t *testing.T) {
	t.Parallel()
	pool := testdb.New(t)
	testdb.Seed(t, pool)
	repo := store.NewTaskRepo(store.New(pool))
	if err := repo.Delete(t.Context(), 1); err != nil {
		t.Fatalf("Delete: %v", err)
	}
	var comments, watchers int
	err := pool.QueryRow(t.Context(), `SELECT
		(SELECT count(*) FROM comments WHERE task_id = 1), (SELECT count(*) FROM task_watchers WHERE task_id = 1)`).
		Scan(&comments, &watchers)
	if err != nil {
		t.Fatal(err)
	}
	if comments != 0 || watchers != 0 {
		t.Errorf("after deleting task 1: %d comments and %d watchers left, want 0", comments, watchers)
	}
}
